 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # gridlines subdivide the canvas into 2x2 mini-cells or 4x4 blocks
    row_lines = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rstarts = [0] + [r + 1 for r in row_lines]
    rends = row_lines + [h]
    cstarts = [0] + [c + 1 for c in col_lines]
    cends = col_lines + [w]
    def which(r, c):
        ri = next(i for i,(a,b) in enumerate(zip(rstarts,rends)) if a <= r < b)
        ci = next(i for i,(a,b) in enumerate(zip(cstarts,cends)) if a <= c < b)
        return ri,ci
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,8):
                marks.setdefault(grid[r][c], []).append(which(r,c))
    # A lone mark indicates a row/column projection; repeated marks on an
    # axis identify a stripe. Color 2 projects vertically, color 3 horizontally.
    row_indices = set()
    col_indices = set()
    for color, points in marks.items():
        if color == 2:
            col_indices.update(c for r,c in points)
        elif color == 3:
            row_indices.update(r for r,c in points)
    # The opposite-color stripe crossing is marked 6.
    for ri in row_indices:
        for r in range(rstarts[ri], rends[ri]):
            for c in range(w):
                if grid[r][c] != 8: out[r][c] = 3
    for ci in col_indices:
        for r in range(h):
            for c in range(cstarts[ci], cends[ci]):
                if grid[r][c] != 8: out[r][c] = 2
    for ri in row_indices:
        for ci in col_indices:
            for r in range(rstarts[ri], rends[ri]):
                for c in range(cstarts[ci], cends[ci]): out[r][c] = 6
    return out
