 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rlines = [r for r in range(h) if all(v == 8 for v in grid[r])]
    clines = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rstarts, rends = [0] + [r+1 for r in rlines], rlines + [h]
    cstarts, cends = [0] + [c+1 for c in clines], clines + [w]
    def cell(r,c):
        ri=next(i for i,(a,b) in enumerate(zip(rstarts,rends)) if a<=r<b)
        ci=next(i for i,(a,b) in enumerate(zip(cstarts,cends)) if a<=c<b)
        return ri,ci
    marks={}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,8): marks.setdefault(grid[r][c],[]).append(cell(r,c))
    # Marked rows and columns are indicated by repeated marks of any color.
    rows=set(); cols=set()
    for pts in marks.values():
        for i in {r for r,c in pts}:
            if sum(r==i for r,c in pts)>=2: rows.add(i)
        for j in {c for r,c in pts}:
            if sum(c==j for r,c in pts)>=2: cols.add(j)
    # The singleton 3 marks the horizontal stripe; paired 2 marks select
    # vertical stripes. A crossing between stripes is colored 6.
    single3=[p for p in marks.get(3,[]) if len(marks.get(3,[]))==1]
    if single3: rows.add(single3[0][0])
    for color,pts in marks.items():
        if color==2:
            cols.update(c for r,c in pts)
        elif color==3 and len(pts)>=2:
            rows.update(r for r,c in pts)
    # Color-2 stripes extend through all selected columns; color-3 stripes through selected rows.
    for j in cols:
        for r in range(h):
            for c in range(cstarts[j],cends[j]):
                if grid[r][c]!=8: out[r][c]=2
    for i in rows:
        for r in range(rstarts[i],rends[i]):
            for c in range(w):
                if grid[r][c]!=8: out[r][c]=3
    # Their overlap is color 6.
    for i in rows:
        for j in cols:
            for r in range(rstarts[i],rends[i]):
                for c in range(cstarts[j],cends[j]): out[r][c]=6
    return out
